def remainderBoxesBossReceipt(readings):
    a=readings
    out=[]
    out=[0]*5
    for x in a: out[x%5]+=1
    return sum((i+1)*x for i,x in enumerate(out))


java
class Solution {
  public int remainderBoxesBossReceipt(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]boxes=new int[5];for(int x:a)boxes[Math.floorMod(x,5)]++;for(int x:boxes)out.add(x);}
    int answer=0;for(int i=0;i<out.size();i++)answer+=(i+1)*out.get(i);return answer;
  }
}
